import sys

def min_paint_to_color_trees(n, m, k, colors, costs):
    # Initialize the dp table where dp[i][j] represents the minimum cost to achieve beauty j with first i trees
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(k + 1):
            if colors[i - 1] != 0:
                if j == 0:
                    continue
                dp[i][j] = dp[i - 1][j]
            else:
                for color in range(1, m + 1):
                    if j > 0:
                        dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + costs[i - 1][color - 1])
                    else:
                        dp[i][j] = min(dp[i][j], dp[i - 1][j] + costs[i - 1][color - 1])

    return dp[n][k]

