def min_paint_needed(n, m, k, colors, prices):
    def can_color_with_beauty(target_beauty):
        dp = [[float('inf')] * (m + 1) for _ in range(n)]
        for j in range(1, m + 1):
            dp[0][j] = prices[0][j - 1]

        for i in range(1, n):
            if colors[i] == 0:
                for j in range(1, m + 1):
                    dp[i][j] = min(dp[i][j], dp[i - 1][j] + prices[i][j - 1])
                    if j != 1:
                        dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + prices[i][j - 1])
            else:
                for j in range(m + 1):
                    dp[i][j] = dp[i - 1][j]

        return min(dp[-1]) <= target_beauty

    low, high = 0, sum(min(prices[i]) for i in range(n))
    while low < high:
        mid = (low + high) // 2
        if can_color_with_beauty(mid):
            high = mid
        else:
            low = mid + 1

    return low if low < sum(min(prices[i]) for i in range(n)) else -1

