    for i in range(1, n + 1):
        for j in range(k + 1):
            if colors[i - 1] == 0:
                for c in range(1, m + 1):
                    cost = paints[i - 1][c - 1]
                    if j > 0 and dp[i - 1][j] < float('inf'):
                        dp[i][j] = min(dp[i][j], dp[i - 1][j] + cost)
                    elif j == 0 and dp[i - 1][j] < float('inf') and j + 1 <= k:
                        dp[i][j + 1] = min(dp[i][j + 1], dp[i - 1][j])
            else:
                if j == 0 and dp[i - 1][j] < float('inf') and j + 1 <= k:
                    dp[i][j + 1] = min(dp[i][j + 1], dp[i - 1][j])

    return dp[n][k] if dp[n][k] != float('inf') else -1

