    def can_beautify_with_cost(target_cost: int) -> bool:
        dp = [float('inf')] * (k + 1)
        dp[0] = 0

        for cost in costs:
            new_dp = dp[:]
            for i in range(k):
                for j, p in enumerate(cost):
                    if p <= target_cost:
                        new_dp[i+1] = min(new_dp[i+1], dp[i] + p)
            dp = new_dp

        return dp[k] < float('inf')

    lo, hi = 0, max(max(row) for row in costs)
    while lo <= hi:
        mid = (lo + hi) // 2
        if can_beautify_with_cost(mid):
