def min_paint_to_color_trees(n, m, k, colors, paints):
    uncolored_indices = [i for i in range(n) if colors[i] == 0]

    if len(uncolored_indices) < k:
        return -1

    def dp(i, current_group_count):
        if i == len(uncolored_indices):
            return 0 if current_group_count == k else float('inf')

        min_cost = float('inf')
        for color in range(1, m + 1):
            cost = dp(i + 1, current_group_count + (1 if current_group_count > 0 else 0))
            if cost != float('inf'):
                min_cost = min(min_cost, cost + paints[uncolored_indices[i]][color - 1])

        return min_cost

    return dp(0, 0)

